import{_ as a,c as t,o as r,ae as n}from"./chunks/framework.Cd-3tpCq.js";const l=JSON.parse('{"title":"Search Synonyms","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/search-synonyms/index.md","filePath":"api/graphql-api/admin/marketing/search-seo/search-synonyms/index.md"}'),o={name:"api/graphql-api/admin/marketing/search-seo/search-synonyms/index.md"};function s(i,e,h,d,c,m){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="search-synonyms" tabindex="-1">Search Synonyms <a class="header-anchor" href="#search-synonyms" aria-label="Permalink to &quot;Search Synonyms&quot;">​</a></h1><p>A <strong>search synonym</strong> is a group of interchangeable search words. When a shopper searches for any word in the group, the storefront also matches products that contain the others. It mirrors the admin <strong>Marketing → Search &amp; SEO → Search Synonyms</strong> screen, and is the main lever for widening storefront search recall.</p><h2 id="how-a-search-synonym-works" tabindex="-1">How a search synonym works <a class="header-anchor" href="#how-a-search-synonym-works" aria-label="Permalink to &quot;How a search synonym works&quot;">​</a></h2><p>A synonym group has just two parts: a label and the words it ties together.</p><ul><li><strong><code>name</code></strong> — a label for the group, used only in the admin list (for example, <code>shirt-group</code>). It does not affect search behaviour.</li><li><strong><code>terms</code></strong> — a comma-separated list of words that are treated as equivalent (for example, <code>shirt,tshirt,tee</code>). A search for any one of them also returns products matching the others, so a query for <code>shirt</code> finds items described as <code>tshirt</code> or <code>tee</code>.</li></ul><p><strong>What it does on the storefront.</strong> Synonyms expand each search query before it runs, so shoppers find relevant products even when their wording differs from the product copy. This raises recall (how many relevant results appear) without you having to re-tag products.</p><p><strong>Relation to other menus.</strong> Synonyms address the gaps revealed by <strong>Search Terms</strong> — phrases shoppers typed that returned few or no results. Reviewing the most-used low-result terms tells you which synonym groups to create.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-list.html">List</a></td><td><code>adminMarketingSearchSynonyms</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-detail.html">Detail</a></td><td><code>adminMarketingSearchSynonym</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-create.html">Create</a></td><td><code>createAdminMarketingSearchSynonym</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-update.html">Update</a></td><td><code>updateAdminMarketingSearchSynonym</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-delete.html">Delete</a></td><td><code>deleteAdminMarketingSearchSynonym</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms-mass-delete.html">Mass Delete</a></td><td><code>createAdminMarketingSearchSynonymMassDelete</code> mutation</td></tr></tbody></table><p>All Search Synonyms operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const y=a(o,[["render",s]]);export{l as __pageData,y as default};
